with flattened_attrs as (select id, array_min(tier_prices) as lowest_price, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, slice(tier_limits, 1, 2) as first_two_limits, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers) select case when avg_tier_price >= 34 then 'LARGE' else 'SMALL' end as avg_tier_price_tier, sum(avg_tier_price) as total_avg_tier_price, min(lowest_price) as min_lowest_price, count(*) as row_count from flattened_attrs group by 1;
